public static List<Round> BuildFromSettings(Context context) throws JSONException {
    String[] stringArray = context.getResources().getStringArray(R.array.presets);
    ArrayList arrayList = new ArrayList();
    for (String str : stringArray) {
        Round round = new Round(context);
        JSONObject jSONObject = new JSONObject(str);
        round.setRepeat(jSONObject.getInt("repeat"));
        round.setTimeSeconds(jSONObject.getLong("time"));
        round.setIntervalSeconds(jSONObject.getLong("interval"));
        arrayList.add(round);
    }
    return arrayList;
}

