    getBindingActivity().ibPause.setVisibility(z ? 8 : 0);
    getBindingActivity().ibBack.setVisibility(0);
}

private void startClock() {
    FragmentUtil.builder(this).replaceFragment(new ClockFragment());
}

private void pause() {
    startBlinkAnimation();
    destroyHandler();
    changeVisibilityButtons(true);
    FocusUtil.define(getBindingActivity().ibPlay);
}

